local data = LJ.Data
local shipped = data.ItemStats
for id, value in pairs(c.items) do shipped.items[id] = value end
shipped.weapons = shipped.weapons or {}
for id, value in pairs(c.weapons) do shipped.weapons[id] = value end
shipped.skills = shipped.skills or {}
for id, value in pairs(c.skills) do shipped.skills[id] = value end
shipped.build = c.build
for id, name in pairs(c.names) do
    local prior = data.Items[id]
    if type(prior) == "string" then
        local _, tail = prior:match("^(.-)(|.*)$")
        if tail then data.Items[id] = name .. tail end
    end
end
for id, fresh in pairs(c.quests) do
    local q = data.Quests[id]
    if q then
        q.name = fresh.name
        if fresh.level then q.level = fresh.level end
        if fresh.xp then q.xp = fresh.xp end
        if fresh.money then q.money = fresh.money end
        if fresh.obj then q.obj = fresh.obj end
        if fresh.choice then q.choice = fresh.choice end
        if fresh.reward then q.reward = fresh.reward end
    end
end
LJ.COLLECT_BUILD = c.build
LJ.COLLECT_COUNTS = { items = 21998, quests = 2003, npcs = 1487 }
